class Verdict(BaseModel):
    """The sealed RCA decision for one run: status, root, conformal candidate set, every
    decision-pool candidate with its trial results, confidence, asks and proposal
    outcomes. Produced by Causentra (pipeline step 9); the only artifact that sets
    the verdict.
    """

    model_config = ConfigDict(extra="forbid", frozen=True)

    schema_version: Annotated[str, StringConstraints(pattern=r"^0\.1\.[0-9]+$")]
    case_id: CaseId
    run_id: RunId
    status: Status
    root: Root | None
    candidate_set: list[VerdictCandidateSet]
    ranked: list[VerdictRanked]
    confidence: Confidence
    asks: list[VerdictAsks]
    ranks_rcaeval: list[
        Annotated[
            str,
            StringConstraints(
                pattern=r"^[a-z0-9][a-z0-9.-]*_(cpu|mem|diskio|socket|latency|error|logs|workload|unknown)$"
            ),
        ]
    ]
    proposals_accepted: list[ProposalId]
    proposals_rejected: list[VerdictProposalsRejected]
    calibration: VerdictCalibration
    params_sha256: Sha256
    verdict_hash: Sha256
